[{"order":1,"type":"heading","text":"Mastering Authentication and Authorization Patterns in Next.js"},{"order":2,"type":"paragraph","text":"Securing modern web applications requires a robust understanding of authentication (who you are) and authorization (what you can do). In the Next.js ecosystem, developers typically choose between managed ecosystem solutions like Auth.js (formerly NextAuth.js) and custom JWT (JSON Web Token) implementations."},{"order":3,"type":"subheading","text":"1. Approach A: Auth.js (NextAuth.js) Implementation"},{"order":4,"type":"paragraph","text":"Auth.js is designed for Next.js to handle complex OAuth, credentials, and session management with minimal boilerplate. Below is the standard configuration using the App Router convention."},{"order":5,"type":"code","text":"// app/api/auth/[...nextauth]/route.ts
import NextAuth from "next-auth";
import GithubProvider from "next-auth/providers/github";

const handler = NextAuth({
  providers: [
    GithubProvider({
      clientId: process.env.GITHUB_ID as string,
      clientSecret: process.env.GITHUB_SECRET as string,
    }),
  ],
  session: {
    strategy: "jwt",
  },
});

export { handler as GET, handler as POST };"},{"order":6,"type":"subheading","text":"2. Approach B: Custom JWT Implementation"},{"order":7,"type":"paragraph","text":"For enterprise applications requiring strict control over cryptographic signing, cookie policies, and payload structures, building a custom JWT auth flow using libraries like 'jose' or 'jsonwebtoken' is preferred."},{"order":8,"type":"code","text":"// lib/auth.ts
import { SignJWT, jwtVerify } from "jose";

const SECRET_KEY = new TextEncoder().encode(process.env.JWT_SECRET);

export async function signToken(payload: any) {
  return await new SignJWT(payload)
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("8h")
    .sign(SECRET_KEY);
}

export async function verifyToken(token: string) {
  try {
    const { payload } = await jwtVerify(token, SECRET_KEY);
    return payload;
  } catch (error) {
    return null;
  }
}"},{"order":9,"type":"subheading","text":"3. Securing Routes with Next.js Middleware"},{"order":10,"type":"paragraph","text":"Middleware executes before requests complete, making it ideal for intercepting unauthorized traffic globally across your application."},{"order":11,"type":"code","text":"// middleware.ts
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { verifyToken } from "@/lib/auth";

export async function middleware(request: NextRequest) {
  const token = request.cookies.get("session")?.value;

  if (!token || !(await verifyToken(token))) {
    return NextResponse.redirect(new URL("/login", request.url));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/dashboard/:path*", "/api/protected/:path*"],
};"},{"order":12,"type":"subheading","text":"Comparison & Best Practices"},{"order":13,"type":"bullet_point","text":"Use Auth.js when integrating multiple OAuth providers (Google, GitHub) quickly without managing database adapters manually."},{"order":14,"type":"bullet_point","text":"Use Custom JWT when your application demands strict multi-tenant claims, specific token rotation strategies, or non-standard token revocation lists."},{"order":15,"type":"bullet_point","text":"Always store tokens in HttpOnly, Secure, SameSite=Strict cookies rather than localStorage to mitigate XSS vulnerabilities."}]
